import{X as e,Y as t,lt as n,n as r}from"./chunks/framework.DAfRfOCC.js";var i=JSON.parse(`{"title":"Avancé","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/advanced.md","filePath":"fr/guide/advanced.md"}`),a={name:`fr/guide/advanced.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="avance" tabindex="-1">Avancé <a class="header-anchor" href="#avance" aria-label="Permalink to “Avancé”">​</a></h1><p>Ce qui se passe sous les objets. Vous n&#39;en avez pas besoin pour dessiner des graphiques ; vous en avez besoin pour écrire vos propres objets, pour tester, ou pour comprendre une surprise.</p><h2 id="evenements-et-bus" tabindex="-1">Événements et bus <a class="header-anchor" href="#evenements-et-bus" aria-label="Permalink to “Événements et bus”">​</a></h2><p>Un événement est un <code>Symbol</code> unique qui porte le type de sa charge (<code>D3PEvent&lt;P&gt;</code>). Deux objets ne peuvent se parler que s&#39;ils tiennent le même symbole : il n&#39;y a pas de noms d&#39;événements en chaînes. Chaque objet a une table de ses propres événements, <code>object.e</code> : <code>axis.e.scaleChanged</code>, <code>chart.e.resized</code>, <code>series.e.dataChanged</code>.</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> off</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bus.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(series.e.dataChanged, () </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;nouvelles données&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">off</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// arrêter d&#39;écouter</span></span></code></pre></div><p>Le bus (<code>D3PBus</code>) <strong>ne livre jamais de façon synchrone</strong> :</p><ul><li>la livraison a lieu dans une microtâche ultérieure, dans l&#39;ordre d&#39;émission (premier entré, premier sorti) ;</li><li>la liste des abonnés est lue au moment de la livraison, donc un abonné peut s&#39;abonner ou se désabonner ;</li><li>une erreur dans un abonné est journalisée et n&#39;arrête pas les autres ;</li><li><code>emit</code> renvoie une promesse ; <code>bus.idle()</code> et <code>d3pSettle(bus)</code> attendent que plus rien ne soit en vol, ce dont les tests ont besoin.</li></ul><p>Les événements par graphique (<code>mousemove</code>, <code>tooltipShow</code>...) s&#39;adressent avec <code>chart.event(&#39;mousemove&#39;)</code>, et portent les types de <code>D3PChartEventMap</code>.</p><h2 id="services" tabindex="-1">Services <a class="header-anchor" href="#services" aria-label="Permalink to “Services”">​</a></h2><p>Chaque graphique tient un registre de services : <code>chart.get(CLÉ)</code>, <code>chart.provide(CLÉ, service)</code>, <code>chart.services.watch(CLÉ, callback)</code>. Une clé est un symbole typé (<code>d3pServiceKey&lt;T&gt;()</code>), donc chacun peut en ajouter. Le gestionnaire d&#39;axes, celui de rendus, les coordonnées, la zone d&#39;interaction, la sonde et la mise en page sont des services du graphique.</p><h2 id="objets-attachables" tabindex="-1">Objets attachables <a class="header-anchor" href="#objets-attachables" aria-label="Permalink to “Objets attachables”">​</a></h2><p>Un objet qui s&#39;attache à des graphiques étend <code>D3PAttachable&lt;D&gt;</code>, où <code>D</code> est ce qu&#39;il garde pour chaque graphique. Il implémente <code>createData(chart)</code> (construire l&#39;état par graphique), <code>attached(chart, data, subs)</code> (s&#39;abonner, créer du DOM ; les abonnements ajoutés à <code>subs</code> sont libérés au détachement) et <code>detached(chart, data)</code> (nettoyer). Il est détaché quand son graphique est détruit. <code>render(chart)</code> est appelé quand il demande un redessin avec <code>tagDirty(chart)</code>.</p><p>Les props se font avec <code>createProps(defaults, { afterSet })</code> : appelables, fusionnées en profondeur, avec un crochet pour redessiner.</p><h2 id="dessiner-par-lots" tabindex="-1">Dessiner par lots <a class="header-anchor" href="#dessiner-par-lots" aria-label="Permalink to “Dessiner par lots”">​</a></h2><p><code>tagDirty</code> ne dessine pas : il met <code>(graphique, objet)</code> en file. Le gestionnaire de rendu du bus dédoublonne la file et l&#39;exécute une fois par image d&#39;animation (<code>requestAnimationFrame</code>, ou un délai sans navigateur). Une demande avec transition l&#39;emporte sur une demande sans transition dans la même image.</p><h2 id="animations" tabindex="-1">Animations <a class="header-anchor" href="#animations" aria-label="Permalink to “Animations”">​</a></h2><p>Un rendu dessine avec une transition (200 ms) quand ses données, ses props ou sa série changent, et sans quand l&#39;échelle change (zoom, déplacement) ou que le graphique est redimensionné.</p><ul><li><strong>Une courbe</strong> garde ce qu&#39;elle montre à l&#39;écran : pour chaque point, sa position en pixels et sa clé, la valeur sur l&#39;axe x d&#39;où il a été placé (un nombre, ou le temps d&#39;une date ; pour des catégories, la position). Un nouveau dessin est une interpolation de ces positions vers les nouvelles, donc une transition interrompue repart de ce qui est visible. La première fois, la courbe grandit depuis la ligne de base, le bas de l&#39;axe. Cacher une série est la même interpolation dans l&#39;autre sens.</li><li><strong>Deux listes de points de longueurs différentes</strong> sont rendues aussi longues l&#39;une que l&#39;autre avant d&#39;être interpolées, en fusionnant les deux listes selon leurs <strong>clés</strong> avec un curseur dans chacune. Les points de même clé sont appariés, quels que soient leurs pixels : un point qui n&#39;a pas changé est apparié à lui-même, même si l&#39;échelle a bougé. Un point sans partenaire est apparié au point le plus proche de l&#39;autre liste (le dernier pris ou le suivant, celui dont la clé est la plus proche). Un point qui apparaît naît sur son voisin et un point qui disparaît meurt sur lui, donc rien ne saute. L&#39;utilitaire est <code>d3pInterpolateSeries(from, to)</code>, où <code>from</code> et <code>to</code> sont <code>{ keys, points }</code> ; il renvoie une fonction de <code>t</code> entre 0 et 1. <code>from</code> peut être un nombre, la ligne de base.</li><li><strong>Les barres</strong> sont appariées par la valeur x de leur point de données (pas par leur indice) : retirer la première ligne ne fait pas prendre à chaque barre la forme de sa voisine. Elles entrent à la base avec une hauteur de 0 et grandissent, et sortent en retournant à la base. Position, taille et couleur sont toutes interpolées.</li><li><strong>Quand des demandes se rencontrent.</strong> Les redessins sont rassemblés par image ; si l&#39;un d&#39;eux vient d&#39;un changement des données, des props ou de la série, le redessin est animé, même si l&#39;échelle change dans la même image (un domaine automatique qui s&#39;ajuste aux nouvelles données). Un changement d&#39;échelle seul (zoom, déplacement) est dessiné aussitôt.</li></ul><h2 id="projections" tabindex="-1">Projections <a class="header-anchor" href="#projections" aria-label="Permalink to “Projections”">​</a></h2><p>Trois mots disent comment une valeur devient une position, et inversement : <code>projectTo</code> va vers les pixels, <code>projectFrom</code> en revient.</p><ul><li><code>axis.projectTo(chart, value)</code> : la position en range d&#39;une valeur ; <code>axis.projectFrom(point)</code> : la valeur sous un point du tracé (un <code>D3PViewportPoint</code>).</li><li><code>system.projectTo(chart, a, b)</code> : le point d&#39;un couple d&#39;unités de range ; <code>system.projectFrom(point)</code> : les unités de range sous un point, <code>undefined</code> hors du système sauf avec <code>{ strict: false }</code>.</li><li><code>renderer.projectTo(chart, x, y)</code> et <code>renderer.projectFrom(point)</code> : toute la chaîne pour un point de données.</li></ul><h3 id="l-evenement-du-pointeur-et-son-cache" tabindex="-1">L&#39;événement du pointeur et son cache <a class="header-anchor" href="#l-evenement-du-pointeur-et-son-cache" aria-label="Permalink to “L&#39;événement du pointeur et son cache”">​</a></h3><p>La zone d&#39;interaction émet un <code>D3PPointerEvent</code> pour chaque événement souris (<code>D3PWheelEvent</code>, <code>D3PDragEvent</code> pour la molette et le glisser). Il porte le pixel (<code>event.point</code>) et c&#39;est un <strong>cache de projections</strong> : rien n&#39;est calculé à l&#39;émission, et ce que demandent l&#39;infobulle, le curseur, les markers ou un outil n&#39;est calculé qu&#39;une fois.</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bus.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(chart.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">event</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;mousemove&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), (</span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">event</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> value</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> xAxis.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">projectFrom</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(event.point, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">undefined</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, event) </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// le cache est le dernier argument</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> again</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> xAxis.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">projectFrom</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(event.point, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">undefined</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, event) </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// pas recalculé</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><p>Tout <code>projectTo</code> et <code>projectFrom</code> prend un <code>D3PProjectionCache</code> optionnel ; le cache est indexé par projecteur, graphique et arguments, donc un événement sert tous les graphiques auxquels il est donné. Un événement est valable jusqu&#39;au prochain redessin : il lit l&#39;état courant du graphique.</p><h3 id="snapshots" tabindex="-1">Snapshots <a class="header-anchor" href="#snapshots" aria-label="Permalink to “Snapshots”">​</a></h3><p>Un geste qui se compare à son point de départ prend un snapshot au lieu de garder l&#39;événement : <code>event.snapshot()</code> renvoie un <code>D3PViewSnapshot</code>, les axes et systèmes du graphique tels qu&#39;ils sont à cet instant (<code>snapshot.getAxis(axis)</code> a le <code>domain</code>, l&#39;échelle et le <code>system</code> figés, avec les mêmes projections). L&#39;outil de déplacement mesure chaque mouvement contre le snapshot de son <code>mousedown</code>, donc il ne dérive pas pendant qu&#39;il écrit le domaine courant.</p><h2 id="la-sonde-et-les-markers" tabindex="-1">La sonde et les markers <a class="header-anchor" href="#la-sonde-et-les-markers" aria-label="Permalink to “La sonde et les markers”">​</a></h2><p><code>d3pProbe(chart)</code> est le service qui dit ce qui est sous un événement du pointeur : <code>probe.projectFrom(event, axis)</code> est la valeur d&#39;un axe (en suivant les jointures, et les événements d&#39;autres graphiques), <code>probe.hit(event, renderer)</code> ce qu&#39;un rendu y trouve (un <code>D3PProbeHit</code> : le point, les formateurs, la couleur, la position, la cellule d&#39;une barre), les deux calculés une fois par événement. L&#39;infobulle est construite à partir des hits.</p><p>Un marker (<code>D3PMarker</code>) montre un hit : <code>show(chart, hit, event)</code>, <code>hide(chart)</code>, <code>remove(chart)</code>. La sonde montre et cache les markers des rendus au fil du pointeur, avec ou sans infobulle.</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">renderer.marker </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">show</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">chart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">hit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">event</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) { </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">/* dessiner */</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hide</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">chart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {}, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">remove</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">chart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {} } </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// le vôtre</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> D3PLineRenderer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ bus, series, marker: </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> D3PDotMarker</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(renderer, { radius: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }) })</span></span></code></pre></div><h2 id="moteurs-de-rendu-d-axe" tabindex="-1">Moteurs de rendu d&#39;axe <a class="header-anchor" href="#moteurs-de-rendu-d-axe" aria-label="Permalink to “Moteurs de rendu d&#39;axe”">​</a></h2><p>Un axe garde le domaine et l&#39;échelle ; un <strong>moteur de rendu d&#39;axe</strong> décide de son apparence. Chaque position a un défaut : <code>D3PCartesianAxisRenderer</code> (les côtés), <code>D3PAngleAxisRenderer</code> (anneau et graduations), <code>D3PRadiusAxisRenderer</code> (un rayon à angle fixe). <code>D3PCursorRadiusAxisRenderer</code> est un axe de rayon dont le trait tourne pour suivre le pointeur ; <code>D3PRadarAngleAxisRenderer</code> dessine le polygone d&#39;un radar.</p><p>Un moteur déclare les positions et les sortes de système qu&#39;il gère, et l&#39;axe lève une erreur explicite quand cela ne convient pas (<code>axis &quot;r&quot; (position &quot;radius&quot;) is not supported by the axis renderer D3PCartesianAxisRenderer; it supports: bottom, top, left, right</code>). Écrivez le vôtre en étendant <code>D3PAxisRenderer</code>.</p><h2 id="vos-propres-objets" tabindex="-1">Vos propres objets <a class="header-anchor" href="#vos-propres-objets" aria-label="Permalink to “Vos propres objets”">​</a></h2><p>Les titres et les légendes sont le modèle : un slot pour la place (voir la <a href="../../fr/guide/layout">mise en page</a>), des props pour les réglages, des services publics pour les données. Les composants standard n&#39;utilisent rien d&#39;autre.</p>`,36)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};